from __future__ import annotations

import json
import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Union

import assemblyai as aai


@dataclass
class TranscriptionResult:
    text: str
    words: Optional[List[Dict[str, Any]]] = None
    utterances: Optional[List[Dict[str, Any]]] = None
    raw: Optional[Dict[str, Any]] = None


def transcribe_with_timestamps(
    audio_url: str,
    *,
    timestamps: str = "word",
    speaker_labels: bool = False,
    language_code: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Transcribe audio using AssemblyAI and return word or segment timestamps.

    Args:
        audio_url: Publicly accessible audio URL.
        timestamps: "word" for word-level timestamps, "segment" for segment/utterance timestamps.
        speaker_labels: Whether to enable speaker labels for segment-style output.
        language_code: Optional language code supported by AssemblyAI.

    Returns:
        Dict with keys:
            - text: transcription text
            - timestamps: list of word or segment timestamp dicts
            - raw: full transcript object as a dict
    """
    api_key = os.environ.get("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise EnvironmentError("ASSEMBLYAI_API_KEY is required")

    aai.settings.api_key = api_key

    config_kwargs: Dict[str, Any] = {}
    if language_code:
        config_kwargs["language_code"] = language_code
    if speaker_labels:
        config_kwargs["speaker_labels"] = True

    config = aai.TranscriptionConfig(**config_kwargs)
    transcript = aai.Transcriber().transcribe(audio_url, config)

    if transcript.status == aai.TranscriptStatus.error:
        raise RuntimeError(f"Transcription failed: {transcript.error}")

    result: Dict[str, Any] = {
        "text": transcript.text,
        "timestamps": [],
        "raw": transcript.json_response if hasattr(transcript, "json_response") else None,
    }

    if timestamps not in {"word", "segment"}:
        raise ValueError('timestamps must be either "word" or "segment"')

    if timestamps == "word":
        words = getattr(transcript, "words", None) or []
        result["timestamps"] = [
            {
                "word": w.text,
                "start": w.start,
                "end": w.end,
                "confidence": getattr(w, "confidence", None),
                "speaker": getattr(w, "speaker", None),
            }
            for w in words
        ]
    else:
        utterances = getattr(transcript, "utterances", None) or []
        if utterances:
            result["timestamps"] = [
                {
                    "speaker": u.speaker,
                    "start": u.start,
                    "end": u.end,
                    "text": u.text,
                    "confidence": getattr(u, "confidence", None),
                }
                for u in utterances
            ]
        else:
            result["timestamps"] = [
                {
                    "speaker": None,
                    "start": getattr(transcript, "start", None),
                    "end": getattr(transcript, "end", None),
                    "text": transcript.text,
                    "confidence": None,
                }
            ]

    return result


def transcription_result_to_timestamps(
    transcript_json: Union[str, Dict[str, Any]],
    timestamps: str = "word",
) -> Dict[str, Any]:
    """
    Normalize an AssemblyAI transcription result into word or segment timestamps.

    This is useful when you already have a transcript response payload.
    """
    if isinstance(transcript_json, str):
        payload = json.loads(transcript_json)
    else:
        payload = transcript_json

    if timestamps not in {"word", "segment"}:
        raise ValueError('timestamps must be either "word" or "segment"')

    text = payload.get("text", "")
    result: Dict[str, Any] = {"text": text, "timestamps": []}

    if timestamps == "word":
        words = payload.get("words") or []
        result["timestamps"] = [
            {
                "word": w.get("text"),
                "start": w.get("start"),
                "end": w.get("end"),
                "confidence": w.get("confidence"),
                "speaker": w.get("speaker"),
            }
            for w in words
        ]
    else:
        utterances = payload.get("utterances") or []
        if utterances:
            result["timestamps"] = [
                {
                    "speaker": u.get("speaker"),
                    "start": u.get("start"),
                    "end": u.get("end"),
                    "text": u.get("text"),
                    "confidence": u.get("confidence"),
                }
                for u in utterances
            ]
        else:
            result["timestamps"] = [
                {
                    "speaker": None,
                    "start": payload.get("start"),
                    "end": payload.get("end"),
                    "text": text,
                    "confidence": None,
                }
            ]

    return result
